//! gRPC and protobuf bindings for `proto/`, generated by `tools/protogen` and committed
//! (regenerate after changing a `.proto`).

/// `clovelly.verifier.v1`: the verifier API.
pub mod verifier {
    include!("proto/clovelly.verifier.v1.rs");
}

/// `clovelly.cell.v1`: the cell API.
pub mod cell {
    include!("proto/clovelly.cell.v1.rs");
}

/// `clovelly.control.v1`: the control plane's customer API and cell channel.
pub mod control {
    include!("proto/clovelly.control.v1.rs");
}

/// `grpc.health.v1`: health checks on the cell API listener.
pub mod health {
    include!("proto/grpc.health.v1.rs");
}

/// Google's launch endorsement messages (vendored from gce-tcb-verifier).
pub mod endorsement {
    include!("proto/cloud_vmm_proto.rs");
}
